import{_ as a,o,c as r,ag as i}from"./chunks/framework.DGzMGr_a.js";const l="/images/class-bpvOqFbtsBwqyqp.jpg",u=JSON.parse('{"title":"刺客攻略 - 技能加点/转职/练级","description":"RO3 刺客 1-99 级技能加点、转职任务、练级路线、配装推荐","frontmatter":{"title":"刺客攻略 - 技能加点/转职/练级","description":"RO3 刺客 1-99 级技能加点、转职任务、练级路线、配装推荐"},"headers":[],"relativePath":"jobs/thief.md","filePath":"jobs/thief.md","lastUpdated":1780230058000}'),e={name:"jobs/thief.md"};function s(n,t,h,d,p,c){return o(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="刺客-推荐搬砖党-操作党" tabindex="-1">刺客（推荐搬砖党/操作党） <a class="header-anchor" href="#刺客-推荐搬砖党-操作党" aria-label="Permalink to &quot;刺客（推荐搬砖党/操作党）&quot;">​</a></h1><p><img src="'+l+'" alt="RO3 刺客职业立绘"></p><p>刺客是 RO3 中打金效率最高的职业，爆伤极高，适合单挑 BOSS 和刷稀有材料。操作要求较高，但收益也最高。</p><h2 id="技能加点" tabindex="-1">技能加点 <a class="header-anchor" href="#技能加点" aria-label="Permalink to &quot;技能加点&quot;">​</a></h2><p><strong>1-10 级</strong>：点满「双持」（核心被动，提升双刀伤害），「残影」点 3 级（加回避）</p><p><strong>11-30 级</strong>：点满「背刺」（核心输出技能，从背后攻击伤害翻倍），「偷窃」点 3 级（搬砖用）</p><p><strong>31-60 级</strong>：点满「隐匿」（潜行绕后接背刺），「毒刃」点满（持续伤害+减速）</p><p><strong>61-99 级</strong>：点满「致命毒」（毒系爆发），「音速投掷」点满（远程起手技），剩余点「回避强化」</p><h2 id="转职任务流程-20级转职" tabindex="-1">转职任务流程（20级转职） <a class="header-anchor" href="#转职任务流程-20级转职" aria-label="Permalink to &quot;转职任务流程（20级转职）&quot;">​</a></h2><ol><li>梦罗克找「盗贼公会会长」（坐标 80,110），接取任务</li><li>去金字塔 1 层击杀 10 只「木乃伊」，获得「绷带碎片」</li><li>收集 10 个「毒囊」（蚂蚁洞毒蛇掉落，概率 25%）</li><li>提交任务，完成转职</li></ol><h2 id="各等级段练级点" tabindex="-1">各等级段练级点 <a class="header-anchor" href="#各等级段练级点" aria-label="Permalink to &quot;各等级段练级点&quot;">​</a></h2><ul><li><strong>1-20 级</strong>：南门平原刷波利（双持普攻快速升级）</li><li><strong>21-40 级</strong>：蚂蚁洞刷蚂蚁卵（背刺秒杀，经验效率高）</li><li><strong>41-60 级</strong>：金字塔 1 层刷木乃伊（毒刃+背刺 combo）</li><li><strong>61-99 级</strong>：古城副本 / 米尔顿斯刷铝矿（搬砖+练级两不误）</li></ul><h2 id="配装思路" tabindex="-1">配装思路 <a class="header-anchor" href="#配装思路" aria-label="Permalink to &quot;配装思路&quot;">​</a></h2><ul><li><strong>武器</strong>：双持短剑，优先攻速属性</li><li><strong>防具</strong>：轻甲，回避优先于防御</li><li><strong>饰品</strong>：暴击伤害 &gt; 暴击率 &gt; 攻速</li></ul><h2 id="搬砖推荐" tabindex="-1">搬砖推荐 <a class="header-anchor" href="#搬砖推荐" aria-label="Permalink to &quot;搬砖推荐&quot;">​</a></h2><p>刺客是 RO3 搬砖首选职业：</p><ul><li>偷窃技能获取额外掉落</li><li>高攻速+高爆伤，单刷效率顶级</li><li>刷铝矿/神之金属等材料效率最高</li></ul>',17)])])}const _=a(e,[["render",s]]);export{u as __pageData,_ as default};
